import java.util.*;

public class DistributedDemo {
    static void writeWithDelay(Map<String,String> primary, Map<String,String> replica,
                               String key, String value, long delayMs) {
        primary.put(key, value);
        new Thread(() -> {
            try { Thread.sleep(delayMs); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            replica.put(key, primary.get(key));
        }).start();
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String,String> primary = new HashMap<>();
        Map<String,String> replica = new HashMap<>();
        writeWithDelay(primary, replica, "spell:1", "Fireball", 100);
        System.out.println("Primary right away: " + primary.get("spell:1"));
        System.out.println("Replica right away: " + replica.get("spell:1"));
        Thread.sleep(200);
        System.out.println("Replica after 200ms: " + replica.get("spell:1"));
    }
}

