import java.util.*;

public class IdempotentPayment {
    private static final Map<String, String> processedKeys = new HashMap<>();

    static String processPayment(String idempotencyKey, int amount) {
        if (processedKeys.containsKey(idempotencyKey)) {
            System.out.println("Returning cached result for " + idempotencyKey);
            return processedKeys.get(idempotencyKey);
        }
        System.out.println("processed once: " + idempotencyKey);
        String result = "paid:" + amount;
        processedKeys.put(idempotencyKey, result);
        return result;
    }

    public static void main(String[] args) {
        System.out.println(processPayment("txn-001", 500));
        System.out.println(processPayment("txn-001", 500));
        System.out.println(processPayment("txn-002", 750));
    }
}
